    Options? options,
    required RefreshRequest body,
  }) {
    return options == null
        ? super.authRefreshCreate(
            extra: extra,
            cancelToken: cancelToken,
            options: options,
            body: body,
          )
        : _authRefreshCreateWithOptions(
            extra: extra,
            cancelToken: cancelToken,
            options: options,
            body: body,
          );
  }
}
